 public static class UkubolaAdvancedSetup {
  internal const string Root=MVP.Root,Title=Root+"/Scenes/Menus/AdvancedTitle.unity",Mission=Root+"/Scenes/Levels/E1M1_Advanced.unity",Generated=Root+"/Generated/Phase12",Data=Root+"/Data/Phase12",Prefabs=Root+"/Prefabs/Phase12",Art=Root+"/Art/Sprites/Phase12",Label="E1M1 / THE OUTPOST - ADVANCED";
  internal static readonly WeaponId[] Ids={WeaponId.Fist,WeaponId.Chainsaw,WeaponId.Chaingun,WeaponId.RocketLauncher,WeaponId.PlasmaRifle,WeaponId.EnergyCannon};
  internal static readonly string[] Items={"Chainsaw","Chaingun","RocketLauncher","PlasmaRifle","EnergyCannon","Invulnerability","Berserk","Rockets","Cells"};
  internal static readonly Vector2Int[] Cells={new Vector2Int(2,1),new Vector2Int(4,2),new Vector2Int(4,3),new Vector2Int(3,5),new Vector2Int(12,2),new Vector2Int(1,4),new Vector2Int(3,3),new Vector2Int(6,3),new Vector2Int(7,4)};
  internal static readonly Vector2Int[] EnemyCells={new Vector2Int(4,1),new Vector2Int(14,4)};
  internal static T[] Find<T>(Scene s)where T:Component=>MVP.Find<T>(s);
  internal static T Require<T>(string path)where T:Object=>MVP.Require<T>(path);
  internal static void Check(bool ok,string text){if(!ok)throw new InvalidOperationException(text);}
  private static void Folder(string path){if(AssetDatabase.IsValidFolder(path))return;int i=path.LastIndexOf('/');Check(!string.IsNullOrEmpty(AssetDatabase.CreateFolder(path.Substring(0,i),path.Substring(i+1))),"Cannot create "+path);}
  private static void Dirty(Object o){EditorUtility.SetDirty(o);if(PrefabUtility.IsPartOfPrefabInstance(o))PrefabUtility.RecordPrefabInstancePropertyModifications(o);}
  private static void Copy(string source,string destination){Check(AssetDatabase.CopyAsset(source,destination),"Cannot copy "+source);AssetDatabase.ImportAsset(destination,ImportAssetOptions.ForceSynchronousImport);}
  private static void ImportArt(){foreach(string name in Directory.GetFiles(Art,"*.png")){
    string path=name.Replace('\\','/');var i=AssetImporter.GetAtPath(path) as TextureImporter;Check(i,"Missing importer: "+path);
    bool weapon=Ids.Any(id=>path.EndsWith("/"+id+"_Idle.png")||path.EndsWith("/"+id+"_Fire.png"));
    i.textureType=weapon?TextureImporterType.Default:TextureImporterType.Sprite;i.spriteImportMode=SpriteImportMode.Single;i.spritePixelsPerUnit=path.EndsWith("_Pickup.png")?32:40;i.filterMode=FilterMode.Point;i.mipmapEnabled=false;i.textureCompression=TextureImporterCompression.Uncompressed;i.npotScale=TextureImporterNPOTScale.None;i.alphaIsTransparency=true;i.alphaSource=TextureImporterAlphaSource.FromInput;i.wrapMode=TextureWrapMode.Clamp;
    if(!weapon){var settings=new TextureImporterSettings();i.ReadTextureSettings(settings);settings.spriteAlignment=(int)SpriteAlignment.Center;settings.spritePivot=new Vector2(.5f,.5f);settings.spriteMeshType=SpriteMeshType.FullRect;i.SetTextureSettings(settings);}i.SaveAndReimport();
   }}
  private static void DefineWeapon(WeaponId id,AmmoType ammo,WeaponMode mode,int cost,float interval,float range,float spread,int damage,float speed=12,float radius=0){string path=Data+"/"+id+".asset";if(MVP.Exists(path))return;
   var d=ScriptableObject.CreateInstance<WeaponDefinition>();d.ConfigureAdvanced(id,ammo,mode,cost,interval,range,spread,damage,speed,radius,Require<Texture2D>(Art+"/"+id+"_Idle.png"),Require<Texture2D>(Art+"/"+id+"_Fire.png"));Check(d.IsValid,"Invalid weapon "+id);AssetDatabase.CreateAsset(d,path);AssetDatabase.SaveAssetIfDirty(d);}
  private static void DefinePickup(string name,PickupKind kind,int amount,AmmoType ammo=AmmoType.Bullets,WeaponId weapon=WeaponId.Fist,PowerupKind power=PowerupKind.Invulnerability){string path=Data+"/"+name+"_Pickup.asset";if(MVP.Exists(path))return;var d=ScriptableObject.CreateInstance<PickupDefinition>();d.Configure(name,kind,Require<Sprite>(Art+"/"+name+"_Pickup.png"),amount,ammo,weaponType:weapon);d.ConfigurePowerup(power);Check(d.IsValid,"Invalid pickup "+name);AssetDatabase.CreateAsset(d,path);AssetDatabase.SaveAssetIfDirty(d);}
  private static void DefineEnemy(string name,EnemyAttackKind kind,int hp,int damage,float speed,float range,float interval){string path=Data+"/"+name+".asset";if(MVP.Exists(path))return;var d=ScriptableObject.CreateInstance<EnemyDefinition>();d.Configure(kind,hp,damage,speed,range,interval);Check(d.IsValid,"Invalid enemy "+name);AssetDatabase.CreateAsset(d,path);AssetDatabase.SaveAssetIfDirty(d);}
  private static void Definitions(){DefineWeapon(WeaponId.Fist,AmmoType.Bullets,WeaponMode.Melee,0,.44f,1.65f,0,10);DefineWeapon(WeaponId.Chainsaw,AmmoType.Bullets,WeaponMode.Melee,0,.12f,1.75f,0,7);DefineWeapon(WeaponId.Chaingun,AmmoType.Bullets,WeaponMode.Hitscan,1,.12f,60,3,0);DefineWeapon(WeaponId.RocketLauncher,AmmoType.Rockets,WeaponMode.Projectile,1,.8f,60,0,40,12,3);DefineWeapon(WeaponId.PlasmaRifle,AmmoType.Cells,WeaponMode.Projectile,1,.16f,60,0,15,19);DefineWeapon(WeaponId.EnergyCannon,AmmoType.Cells,WeaponMode.Projectile,40,1.3f,60,0,100,10,5);
   DefinePickup("Chainsaw",PickupKind.Weapon,0,weapon:WeaponId.Chainsaw);DefinePickup("Chaingun",PickupKind.Weapon,20,weapon:WeaponId.Chaingun);DefinePickup("RocketLauncher",PickupKind.Weapon,5,AmmoType.Rockets,WeaponId.RocketLauncher);DefinePickup("PlasmaRifle",PickupKind.Weapon,40,AmmoType.Cells,WeaponId.PlasmaRifle);DefinePickup("EnergyCannon",PickupKind.Weapon,40,AmmoType.Cells,WeaponId.EnergyCannon);DefinePickup("Invulnerability",PickupKind.Powerup,30);DefinePickup("Berserk",PickupKind.Powerup,60,power:PowerupKind.Berserk);
   DefineEnemy("Brute",EnemyAttackKind.Melee,100,20,3.2f,1.75f,1.15f);DefineEnemy("Watcher",EnemyAttackKind.Projectile,90,18,2.4f,10,1.5f);AssetDatabase.SaveAssets();}
  private static void PickupPrefab(string name){string path=Prefabs+"/"+name+".prefab";if(MVP.Exists(path))return;var d=Require<PickupDefinition>(Data+"/"+name+"_Pickup.asset");var go=new GameObject(name);go.layer=LayerMask.NameToLayer("Pickup");try{var item=go.AddComponent<Pickup>();var c=go.GetComponent<SphereCollider>();c.isTrigger=true;c.radius=.5f;c.center=Vector3.up*.4f;var body=go.GetComponent<Rigidbody>();body.isKinematic=true;body.useGravity=false;var visual=new GameObject("Visual");visual.layer=go.layer;visual.transform.SetParent(go.transform,false);visual.transform.localPosition=Vector3.up*.43f;var renderer=visual.AddComponent<SpriteRenderer>();renderer.sprite=d.Sprite;renderer.sharedMaterial=Require<Material>(Root+"/Generated/Phase02/SpriteCutout.mat");visual.AddComponent<Billboard>();item.Configure(d,renderer);Check(PrefabUtility.SaveAsPrefabAsset(go,path),"Cannot save "+path);}finally{Object.DestroyImmediate(go);}}
  private static Sprite Frame(string n,string state,int i=0)=>Require<Sprite>(Art+"/"+n+"_"+state+"_"+i+".png");
  private static void EnemyPrefab(string name,int agentType,int mask){string path=Prefabs+"/"+name+".prefab";if(MVP.Exists(path))return;var d=Require<EnemyDefinition>(Data+"/"+name+".asset");var go=new GameObject(name);go.SetActive(false);try{go.layer=LayerMask.NameToLayer("Enemy");go.AddComponent<Health>().Configure(d.Health,null);var body=go.AddComponent<CapsuleCollider>();body.radius=.32f;body.height=1.6f;body.center=Vector3.up*.8f;var agent=go.AddComponent<NavMeshAgent>();agent.enabled=false;agent.agentTypeID=agentType;agent.radius=.35f;agent.height=1.7f;agent.speed=d.Speed;agent.acceleration=12;agent.angularSpeed=360;agent.stoppingDistance=name=="Brute"?.95f:1.8f;agent.autoBraking=true;agent.baseOffset=0;
    go.AddComponent<EnemyMotor>();go.AddComponent<EnemyAttack>().Configure(Require<GameObject>(UkubolaCombatSetup.ProjectilePath).GetComponent<Projectile>(),mask);var visual=new GameObject("Visual");visual.layer=go.layer;visual.transform.SetParent(go.transform,false);visual.transform.localPosition=Vector3.up*.8f;var r=visual.AddComponent<SpriteRenderer>();r.sharedMaterial=Require<Material>(Root+"/Generated/Phase02/SpriteCutout.mat");var b=visual.AddComponent<Billboard>();go.AddComponent<EnemySpriteView>().Configure(r,b,Enumerable.Range(0,8).Select(i=>Frame(name,"Idle",i)).ToArray(),Enumerable.Range(0,8).Select(i=>Frame(name,"Walk",i)).ToArray(),Frame(name,"Attack"),Frame(name,"Pain"),Frame(name,"Dead"));go.AddComponent<EnemyBrain>().SetDefinition(d);go.AddComponent<EnemyFaction>().Configure(name=="Brute"?3:4);if(name=="Watcher")go.AddComponent<FloatingEnemyMotor>();go.SetActive(true);Check(PrefabUtility.SaveAsPrefabAsset(go,path),"Cannot save "+path);}finally{Object.DestroyImmediate(go);}}
  private static void SectorMaterials(){var shader=Require<Shader>(Root+"/Art/Shaders/UkubolaSector.shader");Check(shader.isSupported,"Sector shader not supported");foreach(string n in new[]{"Floor","Ceiling","Wall"}){string path=Generated+"/"+n+".mat";if(MVP.Exists(path))continue;var previous=Require<Material>(Root+"/Generated/Phase03/"+n+".mat");var mat=new Material(shader);mat.SetTexture("_BaseMap",previous.GetTexture("_BaseMap"));mat.SetColor("_BaseColor",previous.GetColor("_BaseColor"));AssetDatabase.CreateAsset(mat,path);}AssetDatabase.SaveAssets();}
  private static T MakeGraphic<T>(Transform parent,string name,Vector2 min,Vector2 max)where T:UnityEngine.UI.Graphic{var go=new GameObject(name,typeof(RectTransform),typeof(T));var rt=(RectTransform)go.transform;rt.SetParent(parent,false);rt.anchorMin=min;rt.anchorMax=max;rt.offsetMin=rt.offsetMax=Vector2.zero;var graphic=go.GetComponent<T>();graphic.raycastTarget=false;return graphic;}
  private static void ConfigureMission(Scene s){var flow=Find<MenuFlow>(s).Single();var source=flow.Hud.World.Source;var nav=Find<EnemyNavigation>(s).Single();var level=Require<LevelDefinition>(UkubolaLevelSetup.Data);var display=Find<RetroDisplay>(s).Single();var weapons=source.Weapons;
   var used=new HashSet<Vector2Int>(MvpLayout.Enemies.Concat(MvpLayout.Items).Select(p=>p.Cell));foreach(var p in Cells.Concat(EnemyCells))Check(LevelDefinition.Walkable(level.Tile(p.x,p.y))&&used.Add(p),"Invalid additional cell: "+p);
   var agents=source.Enemies.Select(a=>a.GetComponent<NavMeshAgent>()).ToArray();foreach(string n in new[]{"Brute","Watcher"})EnemyPrefab(n,agents[0].agentTypeID,source.Enemies[0].GetComponent<EnemyAttack>().Mask);foreach(string n in Items.Take(7))PickupPrefab(n);AssetDatabase.SaveAssets();
   // Import operations are finished. Reacquire scene components and assets before linking.
   flow=Find<MenuFlow>(s).Single();source=flow.Hud.World.Source;nav=Find<EnemyNavigation>(s).Single();display=Find<RetroDisplay>(s).Single();weapons=source.Weapons;level=Require<LevelDefinition>(UkubolaLevelSetup.Data);
   weapons.ConfigureAdvanced(Ids.Select(id=>Require<WeaponDefinition>(Data+"/"+id+".asset")).ToArray(),Require<GameObject>(UkubolaCombatSetup.ProjectilePath).GetComponent<Projectile>());Dirty(weapons);var sounds=new AudioClip[8];foreach(var id in Ids)sounds[(int)id]=Require<AudioClip>(Root+"/Audio/Phase12/"+id+".wav");flow.Hud.Audio.ConfigureAdvancedClips(sounds);Dirty(flow.Hud.Audio);Undo.AddComponent<Powerup>(source.Player.gameObject);Undo.AddComponent<SectorNoise>(source.Noise.gameObject).Configure(level,LayerMask.GetMask("World","Interactable"));
   var actors=source.Enemies.ToList();foreach(var a in actors)Undo.AddComponent<EnemyFaction>(a.gameObject).Configure(a.Definition.AttackKind==EnemyAttackKind.Hitscan?1:2);
   for(int i=0;i<2;i++){string n=i==0?"Brute":"Watcher";var go=(GameObject)PrefabUtility.InstantiatePrefab(Require<GameObject>(Prefabs+"/"+n+".prefab"),s);go.name=n;go.transform.SetPositionAndRotation(level.Center(EnemyCells[i]),Quaternion.Euler(0,i==0?-90:180,0));var brain=go.GetComponent<EnemyBrain>();brain.Bind(source.Player,weapons.AimCamera,source.Noise,nav);Undo.AddComponent<EntityId>(go);Dirty(brain);Dirty(go.transform);actors.Add(brain);}
   var items=source.Pickups.ToList();var parent=items[0].transform.parent;for(int i=0;i<Items.Length;i++){string n=Items[i];string path=(i<7?Prefabs:UkubolaPickupSetup.Prefabs)+"/"+n+".prefab";var go=(GameObject)PrefabUtility.InstantiatePrefab(Require<GameObject>(path),s);go.name="Advanced "+n;go.transform.SetParent(parent,false);go.transform.position=level.Center(Cells[i]);var item=go.GetComponent<Pickup>();item.BindViewer(weapons.AimCamera);Undo.AddComponent<EntityId>(go);Dirty(go.transform);Dirty(item.Visual.GetComponent<Billboard>());items.Add(item);}
   foreach(var actor in actors)Undo.AddComponent<SectorLighting>(actor.GetComponentInChildren<SpriteRenderer>().gameObject);foreach(var item in items)Undo.AddComponent<SectorLighting>(item.Visual.gameObject);
   source.Configure(items.ToArray(),actors.ToArray(),source.Player,weapons,source.Noise,source.Spawn,source.Readout);Dirty(source);
   var geometry=s.GetRootGameObjects().Single(g=>g.name=="Level Geometry");foreach(var pair in new[]{("Floors","Floor"),("Ceilings","Ceiling"),("Walls","Wall")}){var r=geometry.transform.Find(pair.Item1).GetComponent<MeshRenderer>();r.sharedMaterial=Require<Material>(Generated+"/"+pair.Item2+".mat");Dirty(r);}
   var frame=display.Image.transform;var map=MakeGraphic<RawImage>(frame,"Advanced Automap",new Vector2(.22f,.22f),new Vector2(.78f,.80f));map.enabled=false;var label=MakeGraphic<Text>(frame,"Advanced Status",new Vector2(.02f,.765f),new Vector2(.98f,.81f));label.font=flow.Typeface;label.fontSize=14;label.resizeTextForBestFit=true;label.resizeTextMinSize=8;label.resizeTextMaxSize=28;label.color=new Color(.94f,.84f,.55f);label.alignment=TextAnchor.MiddleLeft;new GameObject("Advanced Automap Controller").AddComponent<Automap>().Configure(level,flow,map,label,source.Player,weapons);
   flow.ConfigureRoute(Title,Mission,Label);Dirty(flow);var context=Find<LevelContext>(s).Single();var so=new SerializedObject(context);so.FindProperty("levelId").stringValue="E1M1_ADVANCED";so.ApplyModifiedPropertiesWithoutUndo();
   EnsureRoutes(s,nav,actors.ToArray(),source.Spawn.Position);MVP.Save(s);
  }
  private static void EnsureRoutes(Scene s,EnemyNavigation nav,EnemyBrain[] actors,Vector3 spawn){try{UkubolaMvpValidator.CheckBaseRoutes(nav.Data,actors,spawn);return;}catch(Exception e){Debug.LogWarning("[UKUBOLA P12] New positions require base navigation repair: "+e.Message);}
   var agent=actors[0].GetComponent<NavMeshAgent>();var settings=NavMesh.GetSettingsByID(agent.agentTypeID);settings.agentRadius=.35f;settings.agentHeight=1.7f;settings.agentClimb=.30f;settings.agentSlope=45;settings.overrideVoxelSize=true;
   var geometry=s.GetRootGameObjects().Single(g=>g.name=="Level Geometry");var sources=new List<NavMeshBuildSource>();var bounds=new Bounds();bool first=true;foreach(string group in new[]{"Floors","Walls"})foreach(var box in geometry.transform.Find(group).GetComponents<BoxCollider>()){if(!box.enabled||box.isTrigger)continue;sources.Add(new NavMeshBuildSource{shape=NavMeshBuildSourceShape.Box,transform=box.transform.localToWorldMatrix*Matrix4x4.Translate(box.center),size=box.size,area=group=="Floors"?0:1});if(first){bounds=box.bounds;first=false;}else bounds.Encapsulate(box.bounds);}Check(!first,"No geometry");bounds.Expand(1);
   foreach(float voxel in new[]{.05f,.04f}){settings.voxelSize=voxel;var data=NavMeshBuilder.BuildNavMeshData(settings,sources,bounds,Vector3.zero,Quaternion.identity);if(!data)continue;try{UkubolaMvpValidator.CheckBaseRoutes(data,actors,spawn);}catch(Exception e){Object.DestroyImmediate(data);Debug.LogWarning(e.Message);continue;}string path=AssetDatabase.GenerateUniqueAssetPath(Generated+"/AdvancedNavMesh.asset");AssetDatabase.CreateAsset(data,path);AssetDatabase.SaveAssets();nav.Configure(Require<NavMeshData>(path));Dirty(nav);return;}throw new InvalidOperationException("No base NavMesh candidate connects all six actors. Original MVP untouched.");}
  private static void Register(){EditorBuildSettings.scenes=EditorBuildSettings.scenes.Where(x=>x.path!=Title&&x.path!=Mission).Concat(new[]{new EditorBuildSettingsScene(Title,true),new EditorBuildSettingsScene(Mission,true)}).ToArray();}
  [MenuItem("Tools/UKUBOLA/Phase 12/Setup Advanced",false,120)]public static void Setup(){if(!MVP.CanRun()||!EditorSceneManager.SaveCurrentModifiedScenesIfUserWantsTo())return;try{if(MVP.Exists(Title)||MVP.Exists(Mission)){Check(MVP.Exists(Title)&&MVP.Exists(Mission),"Partial setup: read README recovery");ValidateInternal();Register();Debug.Log("[UKUBOLA P12] Existing Advanced preserved. VALIDATION PASSED | 0 errors.");return;}
   UkubolaMvpValidator.CheckMission(EditorSceneManager.OpenScene(MVP.Mission,OpenSceneMode.Single));UkubolaMvpValidator.CheckTitle(EditorSceneManager.OpenScene(MVP.Title,OpenSceneMode.Single));Folder(Generated);Folder(Data);Folder(Prefabs);ImportArt();Definitions();SectorMaterials();Copy(MVP.Mission,Mission);Copy(MVP.Title,Title);ConfigureMission(EditorSceneManager.OpenScene(Mission,OpenSceneMode.Single));var t=EditorSceneManager.OpenScene(Title,OpenSceneMode.Single);var f=Find<MenuFlow>(t).Single();f.ConfigureRoute(Title,Mission,Label);Dirty(f);MVP.Save(t);ValidateInternal();Register();Debug.Log("[UKUBOLA P12] Advanced generated. MVP preserved. VALIDATION PASSED | 0 errors.");}catch(Exception e){Debug.LogError("[UKUBOLA P12] Setup stopped: "+e+"\nSee README recovery.");}}
  internal static void ValidateInternal(){UkubolaAdvancedValidator.CheckMission(EditorSceneManager.OpenScene(Mission,OpenSceneMode.Single));UkubolaAdvancedValidator.CheckTitle(EditorSceneManager.OpenScene(Title,OpenSceneMode.Single));}
  [MenuItem("Tools/UKUBOLA/Phase 12/Open Advanced Title",false,121)]public static void OpenTitle(){Open(Title);}
  [MenuItem("Tools/UKUBOLA/Phase 12/Open Advanced Mission",false,122)]public static void OpenMission(){Open(Mission);}
  private static void Open(string path){if(MVP.CanRun()&&EditorSceneManager.SaveCurrentModifiedScenesIfUserWantsTo()){try{Require<SceneAsset>(path);EditorSceneManager.OpenScene(path,OpenSceneMode.Single);}catch(Exception e){Debug.LogError(e.Message);}}}
  [MenuItem("Tools/UKUBOLA/Phase 12/Validate Advanced",false,123)]public static void Validate(){if(!MVP.CanRun()||!EditorSceneManager.SaveCurrentModifiedScenesIfUserWantsTo())return;try{ValidateInternal();foreach(string path in new[]{Title,Mission})Check(EditorBuildSettings.scenes.Count(x=>x.enabled&&x.path==path)==1,"Scene not registered: "+path);Debug.Log("[UKUBOLA P12] VALIDATION PASSED | 0 errors.");}catch(Exception e){Debug.LogError("[UKUBOLA P12] VALIDATION FAILED: "+e);}}
  [MenuItem("Tools/UKUBOLA/Phase 12/Build Windows Advanced",false,125)]public static void Build(){if(!MVP.CanRun()||!EditorSceneManager.SaveCurrentModifiedScenesIfUserWantsTo())return;try{Check(EditorUserBuildSettings.activeBuildTarget==BuildTarget.StandaloneWindows64&&BuildPipeline.IsBuildTargetSupported(BuildTargetGroup.Standalone,BuildTarget.StandaloneWindows64),"Select Windows x64 and install Build Support");ValidateInternal();string folder=Path.Combine(Directory.GetParent(Application.dataPath).FullName,"Builds","UKUBOLA_ADVANCED_"+DateTime.Now.ToString("yyyyMMdd_HHmmss_fff"));Directory.CreateDirectory(folder);var result=BuildPipeline.BuildPlayer(new BuildPlayerOptions{scenes=new[]{Title,Mission},target=BuildTarget.StandaloneWindows64,locationPathName=Path.Combine(folder,"UKUBOLA.exe"),options=BuildOptions.None});Check(result.summary.result==BuildResult.Succeeded,"Build failed");Debug.Log("[UKUBOLA P12] WINDOWS BUILD SUCCEEDED | "+folder);EditorUtility.RevealInFinder(folder);}catch(Exception e){Debug.LogError("[UKUBOLA P12] BUILD FAILED: "+e);}}
 }
